import React, { useEffect, useState } from "react";
import axios from "../utils/axios";
import toast from "react-hot-toast";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  Legend,
} from "recharts";
import { motion } from "framer-motion";

const COLORS = ["#6366f1", "#8b5cf6", "#06b6d4", "#10b981", "#f59e0b", "#ef4444"];

const KPICard = ({ label, value, sub, delay = 0, accent = false }) => (
  <motion.div
    initial={{ opacity: 0, y: 16 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.4, delay }}
    style={{
      background: accent ? "#6366f1" : "#ffffff",
      color: accent ? "#ffffff" : "#111827",
      border: accent ? "none" : "1px solid #f1f3f5",
      borderRadius: "14px",
      padding: "24px",
      boxShadow: accent
        ? "0 8px 24px rgba(99,102,241,0.25)"
        : "0 1px 4px rgba(0,0,0,0.05)",
      display: "flex",
      flexDirection: "column",
      gap: "6px",
      minWidth: 0,
    }}
  >
    <span
      style={{
        fontSize: "12px",
        fontWeight: 500,
        letterSpacing: "0.06em",
        textTransform: "uppercase",
        color: accent ? "rgba(255,255,255,0.72)" : "#6b7280",
        fontFamily: "'DM Sans', sans-serif",
      }}
    >
      {label}
    </span>
    <span
      style={{
        fontSize: "28px",
        fontWeight: 700,
        letterSpacing: "-0.02em",
        fontFamily: "'DM Sans', sans-serif",
        lineHeight: 1.1,
      }}
    >
      {value}
    </span>
    {sub && (
      <span
        style={{
          fontSize: "13px",
          color: accent ? "rgba(255,255,255,0.65)" : "#9ca3af",
          fontFamily: "'DM Sans', sans-serif",
        }}
      >
        {sub}
      </span>
    )}
  </motion.div>
);

const ChartCard = ({ title, subtitle, onClear, children, delay = 0 }) => (
  <motion.div
    initial={{ opacity: 0, y: 16 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ duration: 0.45, delay }}
    style={{
      background: "#ffffff",
      border: "1px solid #f1f3f5",
      borderRadius: "14px",
      padding: "24px",
      boxShadow: "0 1px 4px rgba(0,0,0,0.05)",
      minWidth: 0,
    }}
  >
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "flex-start",
        marginBottom: "20px",
      }}
    >
      <div>
        <h2
          style={{
            fontSize: "15px",
            fontWeight: 600,
            color: "#111827",
            margin: 0,
            fontFamily: "'DM Sans', sans-serif",
          }}
        >
          {title}
        </h2>
        <p
          style={{
            fontSize: "12px",
            color: "#9ca3af",
            margin: "3px 0 0",
            fontFamily: "'DM Sans', sans-serif",
          }}
        >
          {subtitle}
        </p>
      </div>
      {onClear && (
        <button
          onClick={onClear}
          style={{
            fontSize: "12px",
            color: "#6366f1",
            background: "none",
            border: "none",
            cursor: "pointer",
            fontFamily: "'DM Sans', sans-serif",
          }}
        >
          Clear filter ×
        </button>
      )}
    </div>
    {children}
  </motion.div>
);

const EmptyState = ({ message }) => (
  <div
    style={{
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      height: "160px",
      color: "#9ca3af",
      fontSize: "14px",
      fontFamily: "'DM Sans', sans-serif",
    }}
  >
    {message}
  </div>
);

const CustomBarTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          background: "#fff",
          border: "1px solid #f1f3f5",
          borderRadius: "8px",
          padding: "10px 14px",
          fontSize: "13px",
          fontFamily: "'DM Sans', sans-serif",
          boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
        }}
      >
        <p style={{ margin: 0, color: "#6b7280" }}>{label}</p>
        <p style={{ margin: "4px 0 0", fontWeight: 600, color: "#111827" }}>
          RM {payload[0].value.toFixed(2)}
        </p>
      </div>
    );
  }
  return null;
};

const CustomPieTooltip = ({ active, payload }) => {
  if (active && payload && payload.length) {
    return (
      <div
        style={{
          background: "#fff",
          border: "1px solid #f1f3f5",
          borderRadius: "8px",
          padding: "10px 14px",
          fontSize: "13px",
          fontFamily: "'DM Sans', sans-serif",
          boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
        }}
      >
        <p style={{ margin: 0, color: "#6b7280" }}>{payload[0].name}</p>
        <p style={{ margin: "4px 0 0", fontWeight: 600, color: "#111827" }}>
          RM {payload[0].value.toFixed(2)}
        </p>
      </div>
    );
  }
  return null;
};

const Dashboard = () => {
  const [budgets, setBudgets] = useState([]);
  const [expenses, setExpenses] = useState([]);
  const [selectedMonth, setSelectedMonth] = useState(null);
  const [loading, setLoading] = useState(true);

  const userName = localStorage.getItem("name") || "there";

  useEffect(() => {
    const fetchData = async () => {
      try {
        const userId = localStorage.getItem("userId");
        if (!userId) {
          toast.error("User not logged in");
          return;
        }

        // Fetch budgets with userId param (includes nested expenses)
        const budRes = await axios.get("/api/budgets", {
          params: { userId },
        });

        const budgetsData = Array.isArray(budRes.data) ? budRes.data : [];
        setBudgets(budgetsData);

        // Flatten all expenses from budgets
        const allExpenses = budgetsData.flatMap((b) =>
          (b.expenses || []).map((e) => ({
            ...e,
            budget: { icon: b.icon, name: b.name },
          }))
        );
        setExpenses(allExpenses);
      } catch (err) {
        console.error(err);
        toast.error("Failed to load dashboard data");
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  const totalSpent = expenses.reduce((sum, e) => sum + (e.amount || 0), 0);
  const totalBudget = budgets.reduce((sum, b) => sum + (b.amount || 0), 0);
  const remaining = totalBudget - totalSpent;

  const topBudget = budgets.reduce(
    (top, current) => {
      const currentSpent = (current.expenses || []).reduce((sum, e) => sum + (e.amount || 0), 0);
      return currentSpent > top.amount ? { name: current.name, amount: currentSpent } : top;
    },
    { name: "None", amount: 0 }
  );

  const expensesByMonth = expenses.reduce((map, e) => {
    if (!e.date) return map;
    const date = new Date(e.date);
    const key = date.toLocaleString("default", { month: "long", year: "numeric" });
    map[key] = (map[key] || 0) + (e.amount || 0);
    return map;
  }, {});

  const barData = Object.entries(expensesByMonth).map(([month, amount]) => ({
    month,
    amount,
  }));

  const categoryTotals = budgets
    .map((b) => {
      const filteredExpenses = (b.expenses || []).filter((e) => {
        if (!e.date) return false;
        const date = new Date(e.date);
        const key = date.toLocaleString("default", { month: "long", year: "numeric" });
        return !selectedMonth || key === selectedMonth;
      });
      return {
        name: `${b.icon || ""} ${b.name}`.trim(),
        value: filteredExpenses.reduce((sum, e) => sum + (e.amount || 0), 0),
      };
    })
    .filter((c) => c.value > 0);

  const recentExpenses = [...expenses]
    .sort((a, b) => new Date(b.date) - new Date(a.date))
    .slice(0, 5);

  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "60vh" }}>
        <p style={{ color: "#9ca3af", fontFamily: "'DM Sans', sans-serif" }}>Loading dashboard...</p>
      </div>
    );
  }

  return (
    <>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap');
        .expense-row:hover { background: #fafafa !important; }
        .badge {
          display: inline-flex;
          align-items: center;
          gap: 4px;
          background: #f3f4f6;
          borderRadius: 6px;
          padding: 3px 10px;
          fontSize: 12px;
          fontWeight: 500;
          color: #374151;
          fontFamily: 'DM Sans', sans-serif;
        }
      `}</style>

      <div style={{ padding: "32px", maxWidth: "1200px", margin: "0 auto" }}>
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: -8 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.35 }}
          style={{ marginBottom: "32px" }}
        >
          <h1
            style={{
              fontSize: "22px",
              fontWeight: 700,
              color: "#111827",
              margin: 0,
              fontFamily: "'DM Sans', sans-serif",
            }}
          >
            Hello, {userName} 👋
          </h1>
          <p
            style={{
              fontSize: "14px",
              color: "#9ca3af",
              margin: "4px 0 0",
              fontFamily: "'DM Sans', sans-serif",
            }}
          >
            Here's your spending overview
          </p>
        </motion.div>

        {/* KPI Cards */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))",
            gap: "16px",
            marginBottom: "28px",
          }}
        >
          <KPICard
            label="Total Spent"
            value={`RM ${totalSpent.toFixed(2)}`}
            sub="across all budgets"
            delay={0}
            accent
          />
          <KPICard
            label="Total Budget"
            value={`RM ${totalBudget.toFixed(2)}`}
            sub={`${budgets.length} budget${budgets.length !== 1 ? "s" : ""}`}
            delay={0.07}
          />
          <KPICard
            label="Remaining"
            value={`RM ${remaining.toFixed(2)}`}
            sub={remaining >= 0 ? "within budget" : "over budget"}
            delay={0.14}
          />
          <KPICard
            label="Top Category"
            value={topBudget.name}
            sub={`RM ${topBudget.amount.toFixed(2)} spent`}
            delay={0.21}
          />
        </div>

        {/* Charts */}
        <div
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(auto-fit, minmax(320px, 1fr))",
            gap: "20px",
            marginBottom: "24px",
          }}
        >
          <ChartCard
            title="Monthly Spending"
            subtitle="Click a bar to filter categories"
            delay={0.2}
          >
            {barData.length === 0 ? (
              <EmptyState message="No expense data yet" />
            ) : (
              <ResponsiveContainer width="100%" height={260}>
                <BarChart
                  data={barData}
                  onClick={(e) => {
                    if (e && e.activeLabel) setSelectedMonth(e.activeLabel);
                  }}
                >
                  <XAxis
                    dataKey="month"
                    tick={{ fontSize: 11, fontFamily: "'DM Sans', sans-serif", fill: "#9ca3af" }}
                    axisLine={false}
                    tickLine={false}
                  />
                  <YAxis
                    tick={{ fontSize: 11, fontFamily: "'DM Sans', sans-serif", fill: "#9ca3af" }}
                    axisLine={false}
                    tickLine={false}
                    tickFormatter={(v) => `RM${v}`}
                  />
                  <Tooltip content={<CustomBarTooltip />} cursor={{ fill: "#f3f4f6" }} />
                  <Bar dataKey="amount" fill="#6366f1" radius={[6, 6, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </ChartCard>

          <ChartCard
            title="Spending by Category"
            subtitle={selectedMonth ? `Filtered: ${selectedMonth}` : "All time"}
            onClear={selectedMonth ? () => setSelectedMonth(null) : null}
            delay={0.27}
          >
            {categoryTotals.length === 0 ? (
              <EmptyState message="No category data for this period" />
            ) : (
              <ResponsiveContainer width="100%" height={260}>
                <PieChart>
                  <Pie
                    data={categoryTotals}
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={90}
                    paddingAngle={3}
                    dataKey="value"
                    label={({ name }) => name.split(" ")[0]}
                    labelLine={false}
                  >
                    {categoryTotals.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip content={<CustomPieTooltip />} />
                  <Legend
                    iconType="circle"
                    iconSize={8}
                    wrapperStyle={{
                      fontSize: "12px",
                      fontFamily: "'DM Sans', sans-serif",
                      color: "#6b7280",
                    }}
                  />
                </PieChart>
              </ResponsiveContainer>
            )}
          </ChartCard>
        </div>

        {/* Recent Transactions */}
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.45, delay: 0.34 }}
          style={{
            background: "#ffffff",
            border: "1px solid #f1f3f5",
            borderRadius: "14px",
            overflow: "hidden",
            boxShadow: "0 1px 4px rgba(0,0,0,0.05)",
          }}
        >
          <div
            style={{
              padding: "20px 24px 16px",
              borderBottom: "1px solid #f3f4f6",
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
            }}
          >
            <div>
              <h2
                style={{
                  fontSize: "15px",
                  fontWeight: 600,
                  color: "#111827",
                  margin: 0,
                  fontFamily: "'DM Sans', sans-serif",
                }}
              >
                Recent Transactions
              </h2>
              <p
                style={{
                  fontSize: "12px",
                  color: "#9ca3af",
                  margin: "3px 0 0",
                  fontFamily: "'DM Sans', sans-serif",
                }}
              >
                Last 5 expenses
              </p>
            </div>
            <span
              style={{
                fontSize: "12px",
                color: "#6b7280",
                background: "#f3f4f6",
                borderRadius: "6px",
                padding: "3px 10px",
                fontFamily: "'DM Sans', sans-serif",
                fontWeight: 500,
              }}
            >
              {recentExpenses.length} shown
            </span>
          </div>

          {recentExpenses.length === 0 ? (
            <EmptyState message="No recent expenses" />
          ) : (
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
              <thead>
                <tr style={{ background: "#fafafa" }}>
                  {["Description", "Budget", "Amount", "Date"].map((h) => (
                    <th
                      key={h}
                      style={{
                        padding: "10px 24px",
                        fontSize: "11px",
                        fontWeight: 600,
                        letterSpacing: "0.07em",
                        textTransform: "uppercase",
                        color: "#9ca3af",
                        textAlign: h === "Amount" || h === "Date" ? "right" : "left",
                        fontFamily: "'DM Sans', sans-serif",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {h}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {recentExpenses.map((e) => (
                  <tr
                    key={e.id}
                    className="expense-row"
                    style={{
                      borderTop: "1px solid #f3f4f6",
                      transition: "background 0.15s ease",
                      background: "#ffffff",
                    }}
                  >
                    <td
                      style={{
                        padding: "14px 24px",
                        fontSize: "14px",
                        color: "#111827",
                        fontWeight: 500,
                        fontFamily: "'DM Sans', sans-serif",
                      }}
                    >
                      {e.description}
                    </td>
                    <td style={{ padding: "14px 24px" }}>
                      <span className="badge">
                        {e.budget?.icon} {e.budget?.name}
                      </span>
                    </td>
                    <td
                      style={{
                        padding: "14px 24px",
                        textAlign: "right",
                        fontSize: "14px",
                        fontWeight: 600,
                        color: "#111827",
                        fontFamily: "'DM Sans', sans-serif",
                        whiteSpace: "nowrap",
                      }}
                    >
                      RM {(e.amount || 0).toFixed(2)}
                    </td>
                    <td
                      style={{
                        padding: "14px 24px",
                        textAlign: "right",
                        fontSize: "13px",
                        color: "#9ca3af",
                        fontFamily: "'DM Sans', sans-serif",
                        whiteSpace: "nowrap",
                      }}
                    >
                      {e.date
                        ? new Date(e.date).toLocaleDateString("ms-MY", {
                            year: "numeric",
                            month: "long",
                            day: "numeric",
                          })
                        : "-"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </motion.div>
      </div>
    </>
  );
};

export default Dashboard;
